preConditionHook:
// FRACTAL MOVE, PULLBACK CONTRACTION (Brian's notes P6, pp.14-16). Short as
// written: the latest swing low of `strength` (3, Brian 2026-11-05: three bars
// each side) is the lowest of the last Q swing lows; the move runs down to it
// from the latest swing high before it in the pivot sequence. The bars since
// that low are the pullback: at least `strength` of them (the resolution's
// three bars), at most maxPullbackBars, every one inside the move's range, and
// their mean bar range (high - low) at most R times the move's mean bar range
// (move bars from its high's bar to its low's bar, inclusive). Long mirrors:
// the latest swing high is the highest of the last Q swing highs, the move
// runs up to it from the latest swing low before it. "Highest/lowest" allows a
// tie; fewer than Q pivots of that side in the window means no signal. Fires
// on every bar the conditions hold through the pullback, not once. Ranges are
// summed newest-first.
// PIVOT SEQUENCE -- one inlined form, copied verbatim into every rule of the
// own-rules slice 02 (FractalBoxBreakout, LateFractalFade,
// FractalOrderLowHighHigh, FractalLegSlopeDecay, FractalMovePullbackContraction).
// The merged, NEWEST-FIRST list of the confirmed swing pivots of `strength`
// whose bars lie in the last `pivotLookback` bars, highs and lows in one sequence and
// NON-ALTERNATING (two highs may follow each other). Slot 1 is the newest:
// pT = +1 swing high / -1 swing low, pV = its price, pB = its bars-ago. Only
// the newest four are kept in slots; pivN counts every pivot found, and a
// rule needing m pivots tests pivN >= m -- prices are never trusted through a
// sentinel.
//
// Pivot test hand-rolled as in SwingPivotTarget, because the register lists
// SwingHigh's Occurrence 3+ as unmeasured. MEASURED (EL_Swing_Probe.txt): the
// pivot bar is AT OR ABOVE the `strength` OLDER bars and STRICTLY ABOVE the
// `strength` NEWER bars -- the newer bars are the smaller k and take el_gt /
// el_lt, the older el_ge / el_le; confirmation lag exactly `strength` bars, so
// the newest possible pivot has bars-ago `strength`; candidate offsets
// strength .. pivotLookback - 1, the neighbourhood reaching `strength` bars past the
// window, so the deepest bar touched is pivotLookback - 1 + strength. The low side's tie
// sense mirrors the measured high side.
//
// A bar that is BOTH a swing high and a swing low counts as both (Brian
// 2026-11-05), ordered by the bar's colour: a green bar (close > open) made its
// low first and its high second, so in this newest-first list its high is
// pushed first; any other bar is read as red, high followed by low, so its low is
// pushed first. Both entries carry the same bars-ago. No early break,
// matching the twin. Scratch is declared in localVariables (double placement);
// the loop counters are block-scoped.
pivStrength = (int)strength;
pivWindow = (int)pivotLookback;
pivN = 0;
pT1 = 0;
pT2 = 0;
pT3 = 0;
pT4 = 0;
pV1 = 0.0;
pV2 = 0.0;
pV3 = 0.0;
pV4 = 0.0;
pB1 = 0;
pB2 = 0;
pB3 = 0;
pB4 = 0;
upHiN = 0;
upNotTop = false;
upTopV = 0.0;
upTopBar = 0;
upHaveBase = false;
upBaseV = 0.0;
upBaseBar = 0;
dnLoN = 0;
dnNotBot = false;
dnBotV = 0.0;
dnBotBar = 0;
dnHaveBase = false;
dnBaseV = 0.0;
dnBaseBar = 0;
for (int j = pivStrength; j <= pivWindow - 1; ++j) {
    bool okHi = true;
    bool okLo = true;
    for (int k = j - pivStrength; k < j; ++k) {
        if (!el_gt(high[j], high[k])) okHi = false;
        if (!el_lt(low[j], low[k])) okLo = false;
    }
    for (int k = j + 1; k <= j + pivStrength; ++k) {
        if (!el_ge(high[j], high[k])) okHi = false;
        if (!el_le(low[j], low[k])) okLo = false;
    }
    pushA = 0;
    pushB = 0;
    if (okHi && okLo) {
        if (el_gt(close[j], open[j])) {
            pushA = 1;
            pushB = -1;
        }
        else {
            pushA = -1;
            pushB = 1;
        }
    }
    else if (okHi)
        pushA = 1;
    else if (okLo)
        pushA = -1;
    for (int m = 1; m <= 2; ++m) {
        if (m == 1)
            curT = pushA;
        else
            curT = pushB;
        if (curT != 0) {
            if (curT == 1)
                curV = high[j];
            else
                curV = low[j];
            pivN = pivN + 1;
            if (pivN == 1) { pT1 = curT; pV1 = curV; pB1 = j; }
            if (pivN == 2) { pT2 = curT; pV2 = curV; pB2 = j; }
            if (pivN == 3) { pT3 = curT; pV3 = curV; pB3 = j; }
            if (pivN == 4) { pT4 = curT; pV4 = curV; pB4 = j; }
            if (curT == 1) {
                upHiN = upHiN + 1;
                if (upHiN == 1) {
                    upTopV = curV;
                    upTopBar = j;
                }
                if (upHiN >= 2 && upHiN <= Q && el_gt(curV, upTopV)) upNotTop = true;
                if (dnLoN >= 1 && !dnHaveBase) {
                    dnHaveBase = true;
                    dnBaseV = curV;
                    dnBaseBar = j;
                }
            }
            if (curT == -1) {
                dnLoN = dnLoN + 1;
                if (dnLoN == 1) {
                    dnBotV = curV;
                    dnBotBar = j;
                }
                if (dnLoN >= 2 && dnLoN <= Q && el_lt(curV, dnBotV)) dnNotBot = true;
                if (upHiN >= 1 && !upHaveBase) {
                    upHaveBase = true;
                    upBaseV = curV;
                    upBaseBar = j;
                }
            }
        }
    }
}
upFire = false;
upPbSum = 0.0;
upMvSum = 0.0;
upPbMean = 0.0;
upMvMean = 0.0;
upOk = upHiN >= Q && !upNotTop && upHaveBase && upTopBar >= strength && upTopBar <= maxPullbackBars;
if (upOk) {
    for (int i = 0; i <= upTopBar - 1; ++i) {
        if (el_gt(high[i], upTopV) || el_lt(low[i], upBaseV)) upOk = false;
        upPbSum = upPbSum + (high[i] - low[i]);
    }
    for (int i = upTopBar; i <= upBaseBar; ++i) {
        upMvSum = upMvSum + (high[i] - low[i]);
    }
    upPbMean = upPbSum / upTopBar;
    upMvMean = upMvSum / (upBaseBar - upTopBar + 1);
    upFire = upOk && el_le(upPbMean, R * upMvMean);
}
dnFire = false;
dnPbSum = 0.0;
dnMvSum = 0.0;
dnPbMean = 0.0;
dnMvMean = 0.0;
dnOk = dnLoN >= Q && !dnNotBot && dnHaveBase && dnBotBar >= strength && dnBotBar <= maxPullbackBars;
if (dnOk) {
    for (int i = 0; i <= dnBotBar - 1; ++i) {
        if (el_gt(high[i], dnBaseV) || el_lt(low[i], dnBotV)) dnOk = false;
        dnPbSum = dnPbSum + (high[i] - low[i]);
    }
    for (int i = dnBotBar; i <= dnBaseBar; ++i) {
        dnMvSum = dnMvSum + (high[i] - low[i]);
    }
    dnPbMean = dnPbSum / dnBotBar;
    dnMvMean = dnMvSum / (dnBaseBar - dnBotBar + 1);
    dnFire = dnOk && el_le(dnPbMean, R * dnMvMean);
}
